<?php
require_owner();
$users=qall('SELECT u.id,u.name,u.email,u.phone,u.role,u.is_active,u.created_at,(SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) order_count FROM users u ORDER BY u.name,u.id');
$activeAdmins=count(array_filter($users,fn($u)=>in_array($u['role'],['admin','owner'],true)&&(int)$u['is_active']));
?>
<section class="erp-card"><div class="erp-card-head"><div><h2>Tambah Pengguna</h2><p>Buat akun pelanggan atau administrator. Administrator memiliki akses penuh ke ERP.</p></div></div><form method="post" class="erp-form"><input type="hidden" name="action" value="admin_user_create"><input type="hidden" name="csrf" value="<?= e(compliance_csrf()) ?>"><label>Nama<input name="name" maxlength="100" required></label><label>Email<input name="email" type="email" maxlength="150" required></label><label>Password awal<input name="password" type="password" minlength="8" required></label><label>Hak akses<select name="role"><option value="user">Pelanggan</option><option value="admin">Administrator</option><option value="owner">Pemilik</option></select></label><button class="erp-btn">Tambah pengguna</button></form></section>
<section class="erp-card"><div class="erp-card-head"><div><h2>Pengguna & Peran</h2><p>Nonaktifkan akun untuk menghentikan akses login tanpa menghapus riwayat pesanan. Hapus hanya akun yang belum memiliki pesanan.</p></div><span class="erp-pill"><?= count($users) ?> akun</span></div>
<div class="erp-table-wrap"><table><thead><tr><th>Nama</th><th>Kontak</th><th>Peran</th><th>Status</th><th>Pesanan</th><th>Aksi</th></tr></thead><tbody>
<?php foreach($users as $account): $protected=(int)$account['id']===(int)$_SESSION['user']['id']||($account['role']==='admin'&&(int)$account['is_active']&&$activeAdmins<=1); ?>
<tr><td><strong><?= e($account['name']) ?></strong><small><?= e(date('d M Y',strtotime($account['created_at']))) ?></small></td><td><?= e($account['email']?:'-') ?><small><?= e($account['phone']?:'-') ?></small></td><td><?= $account['role']==='owner'?'Pemilik':($account['role']==='admin'?'Administrator':'Pelanggan') ?></td><td><span class="erp-pill"><?= $account['is_active']?'Aktif':'Nonaktif' ?></span></td><td><?= (int)$account['order_count'] ?></td><td>
<?php if($protected): ?><small>Akun dilindungi</small><?php else: ?>
<form method="post" onsubmit="return confirm('<?= $account['is_active']?'Nonaktifkan akses akun ini?':'Aktifkan kembali akun ini?' ?>')"><input type="hidden" name="action" value="admin_user_manage"><input type="hidden" name="csrf" value="<?= e(auth_csrf()) ?>"><input type="hidden" name="user_id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="operation" value="<?= $account['is_active']?'deactivate':'activate' ?>"><button class="erp-btn" type="submit"><?= $account['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form>
<?php if(!(int)$account['order_count']): ?><details><summary>Hapus akun</summary><form method="post" onsubmit="return confirm('Hapus permanen akun ini?')"><input type="hidden" name="action" value="admin_user_manage"><input type="hidden" name="csrf" value="<?= e(auth_csrf()) ?>"><input type="hidden" name="user_id" value="<?= (int)$account['id'] ?>"><input type="hidden" name="operation" value="delete"><label>Ketik nama: <?= e($account['name']) ?><input name="confirmation" required maxlength="100" autocomplete="off"></label><button class="erp-btn" type="submit">Hapus Permanen</button></form></details><?php else: ?><small>Riwayat pesanan dilindungi</small><?php endif; ?>
<?php endif; ?></td></tr>
<?php endforeach; ?></tbody></table></div></section>
<section class="erp-card"><div class="erp-card-head"><h2>Aktivitas Pengelolaan Akun</h2></div><div class="erp-table-wrap"><table><thead><tr><th>Waktu</th><th>Admin</th><th>ID Akun</th><th>Aksi</th></tr></thead><tbody><?php foreach(qall('SELECT a.*,u.name actor FROM user_management_audit a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.id DESC LIMIT 30') as $audit): ?><tr><td><?= e($audit['created_at']) ?></td><td><?= e($audit['actor']??('ID '.$audit['actor_id'])) ?></td><td><?= (int)$audit['user_id'] ?></td><td><?= e(['activate'=>'Aktifkan','deactivate'=>'Nonaktifkan','delete'=>'Hapus'][$audit['action']]??$audit['action']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
